const $=s=>document.querySelector(s),form=$('[data-post-form]'),status=$('[data-post-status]');
async function api(path='',method='GET',body){const r=await fetch('/api/club/posts'+path,{method,cache:'no-store',...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok){if(r.status===401){$('[data-post-panel]').hidden=true;$('[data-post-login]').hidden=false;}throw Error(d.error||'No se pudo completar la operación.');}return d;}
const node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
async function load(){try{const posts=await api('?manage=1');$('[data-post-panel]').hidden=false;$('[data-post-login]').hidden=true;const list=$('[data-post-list]');list.replaceChildren();for(const post of posts){const card=node('article','');card.className='admin-card';card.append(node('h2',post.title),node('p',post.body),node('small',post.category+(post.expires_on?' · hasta '+post.expires_on:'')));const edit=node('button','Editar'),remove=node('button','Eliminar');edit.type=remove.type='button';edit.onclick=()=>{for(const key of ['id','title','body','category','link_url','expires_on'])form.elements[key].value=post[key]||'';form.scrollIntoView({behavior:'instant'});};remove.onclick=async()=>{if(!confirm('¿Eliminar esta publicación?'))return;try{await api('/'+post.id,'DELETE');await load();}catch(e){status.textContent=e.message;}};card.append(edit,remove);list.append(card);}status.textContent='Solo administración puede crear, editar o eliminar. Las publicaciones vigentes aparecen en la sección de noticias.';}catch(e){status.textContent=e.message;}}
form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form)),button=form.querySelector('button');button.disabled=true;try{await api(data.id?'/'+data.id:'','POST',data);form.reset();form.elements.id.value='';await load();status.textContent='Publicación guardada y disponible en las noticias del club.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
$('[data-post-cancel]').onclick=()=>{form.reset();form.elements.id.value='';};void load();
